INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'Raymund Lull: First Missionary to the Moslems, Chapter X (1902)', 'The great lesson of Lull''s life is that our weapons against Islam should never be carnal. Love, and love alone, will conquer. But it must be an all-sacrificing, an all-consuming love — a love that is faithful unto death.', 'love,sacrifice,peace,faithfulness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'The great lesson of Lull''s life is that our weapons against Islam should never be carnal. Love, and love alone, will conquer. But it must be an all-sacrificing, an all-consuming love — a love that is faithful unto death.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'Arabia: The Cradle of Islam, Chapter XXXVI (1900)', 'But Arabia, although it has all this wealth of promise, is not a field for feeble faith.…Arabia needs men who will believe as seeing the Invisible.', 'faith,courage,mission,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'But Arabia, although it has all this wealth of promise, is not a field for feeble faith.…Arabia needs men who will believe as seeing the Invisible.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'The Disintegration of Islam, Chapter V (1916)', 'Not by controversy and not by argument, but by the Spirit of love will such be won for the Christ whose teaching they have already made their ideal.', 'love,humility,mission,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'Not by controversy and not by argument, but by the Spirit of love will such be won for the Christ whose teaching they have already made their ideal.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'The Disintegration of Islam, Chapter V (1916)', 'The Moslem heart and the Moslem world have only one great need — Jesus Christ.', 'mission,love,hope,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'The Moslem heart and the Moslem world have only one great need — Jesus Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 97, 'The Glory of the Impossible (1950)', 'The end of a survey is only the beginning of the missionary enterprise. One man with God at a mission station is a majority. All arithmetic fails when you deal with spiritual realities.', 'faith,courage,mission,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 97 AND text = 'The end of a survey is only the beginning of the missionary enterprise. One man with God at a mission station is a majority. All arithmetic fails when you deal with spiritual realities.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Circumstances may appear to wreck our lives and God''s plans, but God is not helpless among the ruins. Our broken lives are not lost or useless. God''s love is still working. He comes in and takes the calamity and uses it victoriously, working out his wonderful plan of love.', 'providence,suffering,hope,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Circumstances may appear to wreck our lives and God''s plans, but God is not helpless among the ruins. Our broken lives are not lost or useless. God''s love is still working. He comes in and takes the calamity and uses it victoriously, working out his wonderful plan of love.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Obedience to God''s will is the secret of spiritual knowledge and insight. It is not willingness to know, but willingness to do (obey) God''s will that brings enlightenment and certainty regarding spiritual truth.', 'obedience,faith,truth,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Obedience to God''s will is the secret of spiritual knowledge and insight. It is not willingness to know, but willingness to do (obey) God''s will that brings enlightenment and certainty regarding spiritual truth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'To forgive the person who has wronged us, to love our enemy, to conquer pride, to deny the sins that do so easily beset us, to deny ourselves and take up our cross—these all mean sacrifice.', 'forgiveness,love,sacrifice,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'To forgive the person who has wronged us, to love our enemy, to conquer pride, to deny the sins that do so easily beset us, to deny ourselves and take up our cross—these all mean sacrifice.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Righteousness includes honesty. It always tells the truth. It prefers to tell the truth and suffer than lie and escape the punishment.', 'truth,integrity,courage,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Righteousness includes honesty. It always tells the truth. It prefers to tell the truth and suffer than lie and escape the punishment.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Out of honesty and loyalty, trust grows. Trust and confidence is the environment that makes for happiness.', 'integrity,trust,family,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Out of honesty and loyalty, trust grows. Trust and confidence is the environment that makes for happiness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Christian living is bound up with Christian faith; personal faith in God, which brings his power into your life.', 'faith,discipleship,grace,obedience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Christian living is bound up with Christian faith; personal faith in God, which brings his power into your life.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'Cited in Sally Magnusson, The Flying Scotsman (1981)', 'We are all missionaries. We carry our religion with us, or we allow our religion to carry us. Wherever we go, we either bring people nearer to Christ, or we repel them from Christ.', 'mission,discipleship,witness,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'We are all missionaries. We carry our religion with us, or we allow our religion to carry us. Wherever we go, we either bring people nearer to Christ, or we repel them from Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'Nothing is more beautiful than the loveliness of the woods before sunrise. At no other time have I so sharp an understanding of what God means to do with me as in these hours of dawn. When other folk are still asleep, I hear God best and learn His plan.', 'creation,prayer,wonder,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'Nothing is more beautiful than the loveliness of the woods before sunrise. At no other time have I so sharp an understanding of what God means to do with me as in these hours of dawn. When other folk are still asleep, I hear God best and learn His plan.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'If I come here of myself I am lost. But I can do all things through Christ.…I am just the instrument through which He speaks, and I would be able to do more if I were to stay in closer touch with Him. With my prayers I mix my labors, and sometimes God is pleased to bless the results.', 'prayer,humility,service,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'If I come here of myself I am lost. But I can do all things through Christ.…I am just the instrument through which He speaks, and I would be able to do more if I were to stay in closer touch with Him. With my prayers I mix my labors, and sometimes God is pleased to bless the results.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'You have too much religion and not enough Christianity—too many creeds and not enough performance. This world is perishing for kindness.', 'love,compassion,justice,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'You have too much religion and not enough Christianity—too many creeds and not enough performance. This world is perishing for kindness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'I feel most strongly that we have no right to ask God to change fixed laws of the universe. If we plant oats, we must expect to harvest oats and not corn or beans. If we sow hate and wrongdoing in our lives, we must expect to reap the awful results.', 'justice,wisdom,truth,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'I feel most strongly that we have no right to ask God to change fixed laws of the universe. If we plant oats, we must expect to harvest oats and not corn or beans. If we sow hate and wrongdoing in our lives, we must expect to reap the awful results.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'God is going to reveal things to us that He never revealed before if we put our hand in His', 'faith,creation,hope,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'God is going to reveal things to us that He never revealed before if we put our hand in His');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'The most gratifying thing I have found in my years of work is the ever-increasing demand of the youth of the country for knowledge.', 'hope,education,wisdom,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'The most gratifying thing I have found in my years of work is the ever-increasing demand of the youth of the country for knowledge.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'Never a day passes but that I do myself the honor to commune with some of their varied forms.', 'creation,wonder,prayer,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'Never a day passes but that I do myself the honor to commune with some of their varied forms.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'In the South we are sinning against the land…In return it is punishing us.', 'creation,stewardship,justice,repentance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'In the South we are sinning against the land…In return it is punishing us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'My prayers seem to be more of an attitude than anything else. I indulge in very little lip service, but ask the Great Creator silently, daily, and often many times a day, to permit me to speak to Him through the three great Kingdoms of the world which He has created…to understand their relations to each other, and our relations to them and to the Great God Who made all of us.', 'prayer,creation,wisdom,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'My prayers seem to be more of an attitude than anything else. I indulge in very little lip service, but ask the Great Creator silently, daily, and often many times a day, to permit me to speak to Him through the three great Kingdoms of the world which He has created…to understand their relations to each other, and our relations to them and to the Great God Who made all of us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'Cited in Rackham Holt, George Washington Carver: An American Biography (1943)', 'The many good things the Lord has entrusted to my care are too numerous to mention here.', 'gratitude,providence,calling,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'The many good things the Lord has entrusted to my care are too numerous to mention here.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'George Washington Carver: In His Own Words (1987)', 'Divine love acts upon humanity the same everywhere, and Divine love is going to rule the world.', 'love,justice,hope,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'Divine love acts upon humanity the same everywhere, and Divine love is going to rule the world.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 73, 'George Washington Carver: In His Own Words (1987)', 'I want them to see the Great Creator in the smallest and apparently the most insignificant things about them.', 'creation,wonder,wisdom,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 73 AND text = 'I want them to see the Great Creator in the smallest and apparently the most insignificant things about them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'One lesson some of us have come to learn is that in divine service the principle of waste is the principle of power. The principle which determines usefulness is the very principle of scattering.', 'service,sacrifice,devotion,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'One lesson some of us have come to learn is that in divine service the principle of waste is the principle of power. The principle which determines usefulness is the very principle of scattering.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'The service of the Lord is not to be measured by tangible results. No, my friends, the Lord''s first concern is with our position at His feet and our anointing of His head.', 'service,worship,humility,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'The service of the Lord is not to be measured by tangible results. No, my friends, the Lord''s first concern is with our position at His feet and our anointing of His head.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'I have never met a soul who has set out to satisfy the Lord and has not been satisfied himself. It is impossible. Our satisfaction comes unfailingly when we satisfy Him first.', 'joy,devotion,worship,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'I have never met a soul who has set out to satisfy the Lord and has not been satisfied himself. It is impossible. Our satisfaction comes unfailingly when we satisfy Him first.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'The idea of waste only comes into our Christianity when we underestimate the worth of our Lord. The whole question is, How precious is He to us now?', 'worship,love,sacrifice,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'The idea of waste only comes into our Christianity when we underestimate the worth of our Lord. The whole question is, How precious is He to us now?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'God does not set us here first of all to preach or to do work for Him. The first thing for which He sets us here is to create in others a hunger for Himself.', 'witness,service,discipleship,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'God does not set us here first of all to preach or to do work for Him. The first thing for which He sets us here is to create in others a hunger for Himself.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'The Normal Christian Life, Chapter 14 (1957)', 'God''s ways with us are all designed to establish in us this other principle, namely, that our work for Him springs out of our ministering to Him.', 'service,humility,grace,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'God''s ways with us are all designed to establish in us this other principle, namely, that our work for Him springs out of our ministering to Him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 23, 'Sit, Walk, Stand, Chapter 3 (1957)', 'We do not fight in order to win, but because in Christ we have already won. Overcomers are those who rest in the victory already given to them by their God.', 'victory,courage,faith,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 23 AND text = 'We do not fight in order to win, but because in Christ we have already won. Overcomers are those who rest in the victory already given to them by their God.');
