INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 85, 'Cited in Elisabeth Elliot, Shadow of the Almighty (1958)', 'Father, take my life, yea, my blood if Thou wilt, and consume it with Thine enveloping fire. I would not save it, for it is not mine to save. Have it, Lord, have it all. Pour out my life as an oblation for the world. Blood is only of value as it flows before Thine altar.', 'surrender,sacrifice,prayer,mission', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 85 AND text = 'Father, take my life, yea, my blood if Thou wilt, and consume it with Thine enveloping fire. I would not save it, for it is not mine to save. Have it, Lord, have it all. Pour out my life as an oblation for the world. Blood is only of value as it flows before Thine altar.');
