INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 85, 'Cited in Elisabeth Elliot, Shadow of the Almighty (1958)', 'Missionaries are very human folks, just doing what they are asked. Simply a bunch of nobodies trying to exalt Somebody.', 'humility,service,mission,obedience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 85 AND text = 'Missionaries are very human folks, just doing what they are asked. Simply a bunch of nobodies trying to exalt Somebody.');
