INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 85, 'Cited in Elisabeth Elliot, Shadow of the Almighty (1958)', 'Oh the fullness, pleasure, sheer excitement of knowing God on earth. I care not if I ever raise my voice again for Him, if only I may love Him, please Him.', 'joy,love,worship,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 85 AND text = 'Oh the fullness, pleasure, sheer excitement of knowing God on earth. I care not if I ever raise my voice again for Him, if only I may love Him, please Him.');
