INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 95, 'Discipline: The Glad Surrender (1982)', 'Discipline is the wholehearted yes to the call of God. When I know myself called, summoned, addressed, taken possession of, known, acted upon, I have heard the Master.', 'discipline,obedience,calling,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 95 AND text = 'Discipline is the wholehearted yes to the call of God. When I know myself called, summoned, addressed, taken possession of, known, acted upon, I have heard the Master.');
