INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 95, 'Love Has a Price Tag (1979)', 'Prayer is like incense. It costs a great deal. It doesn''t seem to accomplish much (as we mortals assess things). It soon dissipates. But God likes the smell.', 'prayer,faith,worship,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 95 AND text = 'Prayer is like incense. It costs a great deal. It doesn''t seem to accomplish much (as we mortals assess things). It soon dissipates. But God likes the smell.');
