INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 95, 'Through Gates of Splendor, Epilogue II (1981 edition)', 'God is God. If He is God, He is worthy of my worship and my service. I will find rest nowhere but in His will, and that will is infinitely, immeasurably, unspeakably beyond my largest notions of what He is up to.', 'sovereignty,worship,trust,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 95 AND text = 'God is God. If He is God, He is worthy of my worship and my service. I will find rest nowhere but in His will, and that will is infinitely, immeasurably, unspeakably beyond my largest notions of what He is up to.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 98, 'Cited in Russell T. Hitt, Jungle Pilot: The Life and Witness of Nate Saint (1959)', 'Missionaries constantly face expendability. And people who do not know the Lord ask why in the world we waste our lives as missionaries. They forget that they too are expending their lives. They forget that when their lives are spent and the bubble has burst they will have nothing of eternal significance to show for the years they have wasted.', 'calling,sacrifice,mission,eternity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 98 AND text = 'Missionaries constantly face expendability. And people who do not know the Lord ask why in the world we waste our lives as missionaries. They forget that they too are expending their lives. They forget that when their lives are spent and the bubble has burst they will have nothing of eternal significance to show for the years they have wasted.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 98, 'Cited in Russell T. Hitt, Jungle Pilot: The Life and Witness of Nate Saint (1959)', 'In this experience I have not felt particularly close to eternity because I am deeply convinced that we live moment by moment by His tender mercies because He has a job for us to do ere we see Him face to face.', 'providence,trust,purpose,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 98 AND text = 'In this experience I have not felt particularly close to eternity because I am deeply convinced that we live moment by moment by His tender mercies because He has a job for us to do ere we see Him face to face.');
