INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'Humility looks at its merits, gifts, and talents but also looks beyond them to God, the Author of every good and perfect gift, and renders all the glory to God.', 'humility,gratitude,grace,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'Humility looks at its merits, gifts, and talents but also looks beyond them to God, the Author of every good and perfect gift, and renders all the glory to God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 59, 'The Disciplines of the Christian Life (1985)', 'I believe the secret of growth is to develop the devotional life. This involves setting aside time each day for prayer and Bible study. The time need not be long, but it should be unhurried.', 'prayer,scripture,discipleship,discipline', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 59 AND text = 'I believe the secret of growth is to develop the devotional life. This involves setting aside time each day for prayer and Bible study. The time need not be long, but it should be unhurried.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'In my view, there is no conflict in being a rigorous scientist and a person who believes in a God who takes a personal interest in each one of us. Science''s domain is to explore nature. God''s domain is in the spiritual world, a realm not possible to explore with the tools and language of science.', 'faith,creation,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'In my view, there is no conflict in being a rigorous scientist and a person who believes in a God who takes a personal interest in each one of us. Science''s domain is to explore nature. God''s domain is in the spiritual world, a realm not possible to explore with the tools and language of science.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'Science is the only reliable way to understand the natural world, and its tools when properly utilized can generate profound insights into material existence. But science is powerless to answer questions such as "Why did the universe come into being?" "What is the meaning of human existence?" "What happens after we die?"', 'truth,wisdom,humility,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'Science is the only reliable way to understand the natural world, and its tools when properly utilized can generate profound insights into material existence. But science is powerless to answer questions such as "Why did the universe come into being?" "What is the meaning of human existence?" "What happens after we die?"');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'The Big Bang cries out for a divine explanation. It forces the conclusion that nature had a defined beginning. I cannot see how nature could have created itself. Only a supernatural force that is outside of space and time could have done that.', 'creation,sovereignty,wonder,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'The Big Bang cries out for a divine explanation. It forces the conclusion that nature had a defined beginning. I cannot see how nature could have created itself. Only a supernatural force that is outside of space and time could have done that.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'Will we turn our backs on science because it is perceived as a threat to God, abandoning all of the promise of advancing our understanding of nature and applying that to the alleviation of suffering and the betterment of humankind?', 'compassion,service,creation,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'Will we turn our backs on science because it is perceived as a threat to God, abandoning all of the promise of advancing our understanding of nature and applying that to the alleviation of suffering and the betterment of humankind?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'If God exists, then He must be outside the natural world, and therefore the tools of science are not the right ones to learn about Him.', 'faith,truth,seeking,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'If God exists, then He must be outside the natural world, and therefore the tools of science are not the right ones to learn about Him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', '…for me the experience of sequencing the human genome, and uncovering this most remarkable of all texts, was both a stunning scientific achievement and an occasion of worship.', 'worship,creation,wonder,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = '…for me the experience of sequencing the human genome, and uncovering this most remarkable of all texts, was both a stunning scientific achievement and an occasion of worship.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'It is time to call a truce in the escalating war between science and spirit. The war was never really necessary.', 'peace,truth,faith,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'It is time to call a truce in the escalating war between science and spirit. The war was never really necessary.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', '…I found it difficult to imagine that there could be a real conflict between scientific truth and spiritual truth. Truth is truth. Truth cannot disprove truth.', 'truth,faith,wisdom,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = '…I found it difficult to imagine that there could be a real conflict between scientific truth and spiritual truth. Truth is truth. Truth cannot disprove truth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'Prayer is not, as some seem to suggest, an opportunity to manipulate God into doing what you want Him to. Prayer is instead our way of seeking fellowship with God, learning about Him, and attempting to perceive His perspective on the many issues around us that cause us puzzlement, wonder, or distress.', 'prayer,devotion,faith,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'Prayer is not, as some seem to suggest, an opportunity to manipulate God into doing what you want Him to. Prayer is instead our way of seeking fellowship with God, learning about Him, and attempting to perceive His perspective on the many issues around us that cause us puzzlement, wonder, or distress.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', '…I can testify that coming to a knowledge of God''s love and grace is empowering, not constraining. God is in the business of release, not incarceration.', 'grace,love,freedom,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = '…I can testify that coming to a knowledge of God''s love and grace is empowering, not constraining. God is in the business of release, not incarceration.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 75, 'The Language of God (2006)', 'It is humbling for me, and awe-inspiring, to realize that we have caught the first glimpse of our own instruction book, previously known only to God.', 'humility,wonder,creation,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 75 AND text = 'It is humbling for me, and awe-inspiring, to realize that we have caught the first glimpse of our own instruction book, previously known only to God.');
