INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 58, 'Marching Orders for the End Battle (1969)', 'He has no problems, only plans. That is why there is never a panic in heaven. Knowing the future gives us strength and security.', 'sovereignty,peace,hope,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 58 AND text = 'He has no problems, only plans. That is why there is never a panic in heaven. Knowing the future gives us strength and security.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 58, 'He Cares, He Comforts (1977)', '…we never touch the ocean of God''s love so much as when we love our enemies. It is a joy to accept forgiveness, but it is almost a greater joy to give forgiveness.', 'love,forgiveness,joy,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 58 AND text = '…we never touch the ocean of God''s love so much as when we love our enemies. It is a joy to accept forgiveness, but it is almost a greater joy to give forgiveness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 58, 'He Cares, He Comforts (1977)', 'Jesus can bring peace and rejoicing into your heart, even in the midst of your pain. God knows of your every suffering and problem as no human can.', 'peace,suffering,compassion,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 58 AND text = 'Jesus can bring peace and rejoicing into your heart, even in the midst of your pain. God knows of your every suffering and problem as no human can.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 58, 'Tramp for the Lord (1974)', '…trying to do the Lord''s work in your own strength is the most confusing, exhausting, and tedious of all work. But when you are filled with the Holy Spirit, then the ministry of Jesus just flows out of you.', 'service,humility,discipleship,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 58 AND text = '…trying to do the Lord''s work in your own strength is the most confusing, exhausting, and tedious of all work. But when you are filled with the Holy Spirit, then the ministry of Jesus just flows out of you.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 58, 'Tramp for the Lord (1974)', 'I can declare that the deepest darkness is outshone by the light of Jesus.', 'hope,faith,courage,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 58 AND text = 'I can declare that the deepest darkness is outshone by the light of Jesus.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 71, 'Cited in John Elliot Drinkwater Bethune, The Life of Galileo Galilei, with Illustrations of the Advancement of Experimental Philosophy (1830)', 'But I do not hold it necessary to believe, that the same God who has endowed us with senses, with speech, and intellect, intended that we should neglect the use of these, and seek by other means for knowledge which they are sufficient to procure us…', 'truth,wisdom,scripture,creation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 71 AND text = 'But I do not hold it necessary to believe, that the same God who has endowed us with senses, with speech, and intellect, intended that we should neglect the use of these, and seek by other means for knowledge which they are sufficient to procure us…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 71, 'Cited in John Elliot Drinkwater Bethune, The Life of Galileo Galilei, with Illustrations of the Advancement of Experimental Philosophy (1830)', 'I at least will not be so wilfully wrong, and so ungrateful to nature and to God, that having been gifted with sense and language, I should voluntarily set less value on such great endowments than on the fallacies of a fellow man, and blindly and blunderingly believe whatever I hear, and barter the freedom of my intellect for slavery to one as liable to error as myself.', 'truth,courage,gratitude,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 71 AND text = 'I at least will not be so wilfully wrong, and so ungrateful to nature and to God, that having been gifted with sense and language, I should voluntarily set less value on such great endowments than on the fallacies of a fellow man, and blindly and blunderingly believe whatever I hear, and barter the freedom of my intellect for slavery to one as liable to error as myself.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 71, 'Cited in John Elliot Drinkwater Bethune, The Life of Galileo Galilei, with Illustrations of the Advancement of Experimental Philosophy (1830)', 'Alas! your dear friend and servant Galileo has become totally and irreparably blind; so that this heaven, this earth, this universe, which with wonderful observations I had enlarged a hundred and thousand times beyond the belief of by-gone ages, henceforward for me is shrunk into the narrow space which I myself fill in it.—So it pleases God: it shall therefore please me also.', 'suffering,surrender,providence,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 71 AND text = 'Alas! your dear friend and servant Galileo has become totally and irreparably blind; so that this heaven, this earth, this universe, which with wonderful observations I had enlarged a hundred and thousand times beyond the belief of by-gone ages, henceforward for me is shrunk into the narrow space which I myself fill in it.—So it pleases God: it shall therefore please me also.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 71, 'The Starry Messenger, Dedication (1610)', '…may you enjoy for many years those good blessings, which are sent to you not so much from the stars as from God, the Maker and Governor of the stars.', 'providence,gratitude,creation,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 71 AND text = '…may you enjoy for many years those good blessings, which are sent to you not so much from the stars as from God, the Maker and Governor of the stars.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Dioptrice, Preface (1611)', 'O telescope, instrument of much knowledge, more precious than any sceptre! Is not he who holds thee in his hand made king and lord of the works of God?', 'creation,wonder,wisdom,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = 'O telescope, instrument of much knowledge, more precious than any sceptre! Is not he who holds thee in his hand made king and lord of the works of God?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Cited in John Elliot Drinkwater Bethune, Life of Kepler (1830)', '…as often as he lifts up to this goodly heaven those eyes with which alone he is able to see, let him pour out his heart in praises and thanksgiving to God the Creator; and let him not fear but he is offering a worship not less acceptable than his to whom God has granted to see yet more clearly with the eyes of his mind…', 'worship,gratitude,creation,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = '…as often as he lifts up to this goodly heaven those eyes with which alone he is able to see, let him pour out his heart in praises and thanksgiving to God the Creator; and let him not fear but he is offering a worship not less acceptable than his to whom God has granted to see yet more clearly with the eyes of his mind…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Cited in John Elliot Drinkwater Bethune, Life of Kepler (1830)', '…although, even now, we are perhaps erring something from the truth, yet it is better, by working on, to show our industry, than our laziness by neglect.', 'perseverance,work,truth,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = '…although, even now, we are perhaps erring something from the truth, yet it is better, by working on, to show our industry, than our laziness by neglect.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Cited in John Elliot Drinkwater Bethune, Life of Kepler (1830)', '…I cannot reflect without consternation that I should have been so given up by God to my own intemperance, as to shut my eyes on all these benefits…', 'humility,repentance,gratitude,reconciliation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = '…I cannot reflect without consternation that I should have been so given up by God to my own intemperance, as to shut my eyes on all these benefits…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Cited in John Elliot Drinkwater Bethune, Life of Kepler (1830)', 'The intense pleasure I have received from this discovery never can be told in words. I regretted no more the time wasted; I tired of no labour…', 'joy,work,perseverance,creation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = 'The intense pleasure I have received from this discovery never can be told in words. I regretted no more the time wasted; I tired of no labour…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Cited in John Elliot Drinkwater Bethune, Life of Kepler (1830)', '…the die is cast, the book is written; to be read either now or by posterity, I care not which: it may well wait a century for a reader, as God has waited six thousand years for an observer.', 'patience,providence,courage,work', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = '…the die is cast, the book is written; to be read either now or by posterity, I care not which: it may well wait a century for a reader, as God has waited six thousand years for an observer.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Harmonices Mundi, Book V, Chapter 7 (1619)', '…man, the ape of his Creator, should finally have discovered the art of singing polyphonically…that he might to some extent taste the satisfaction of God the Workman with His own works, in that very sweet sense of delight elicited from this music which imitates God.', 'creation,joy,beauty,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = '…man, the ape of his Creator, should finally have discovered the art of singing polyphonically…that he might to some extent taste the satisfaction of God the Workman with His own works, in that very sweet sense of delight elicited from this music which imitates God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Harmonices Mundi, Book V, Chapter 9 (1619)', 'Holy Father, keep us safe in the concord of our love for one another…just as through the sweetest bonds of harmonies Thou hast made all Thy works one; and that from the bringing of Thy people into concord the body of Thy Church may be built up in the Earth, as Thou didst erect the heavens themselves out of harmonies.', 'unity,love,peace,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = 'Holy Father, keep us safe in the concord of our love for one another…just as through the sweetest bonds of harmonies Thou hast made all Thy works one; and that from the bringing of Thy people into concord the body of Thy Church may be built up in the Earth, as Thou didst erect the heavens themselves out of harmonies.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Harmonices Mundi, Book V, Chapter 9 (1619)', 'For in geometrical things, which are subject to free choice, God chose nothing without a geometrical cause of some sort, as is apparent in the edges of leaves, in the scales of fishes, in the skins of beasts and their spots and the order of the spots, and similar things.', 'creation,wisdom,beauty,wonder', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = 'For in geometrical things, which are subject to free choice, God chose nothing without a geometrical cause of some sort, as is apparent in the edges of leaves, in the scales of fishes, in the skins of beasts and their spots and the order of the spots, and similar things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 72, 'Harmonices Mundi, Book V, Chapter 9 (1619)', 'Behold! now, I have completed the work of my profession, having employed as much power of mind as Thou didst give to me; to the men who are going to read those demonstrations I have made manifest the glory of Thy works, as much of its infinity as the narrows of my intellect could apprehend.', 'humility,work,calling,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 72 AND text = 'Behold! now, I have completed the work of my profession, having employed as much power of mind as Thou didst give to me; to the men who are going to read those demonstrations I have made manifest the glory of Thy works, as much of its infinity as the narrows of my intellect could apprehend.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'The Principia: Mathematical Principles of Natural Philosophy, General Scholium (1713)', 'We know him only by his most wise and excellent contrivances of things, and final causes; we admire him for his perfections; but we reverence and adore him on account of his dominion. For we adore him as his servants; and a God without dominion, providence, and final causes, is nothing else but Fate and Nature.', 'worship,providence,sovereignty,creation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'We know him only by his most wise and excellent contrivances of things, and final causes; we admire him for his perfections; but we reverence and adore him on account of his dominion. For we adore him as his servants; and a God without dominion, providence, and final causes, is nothing else but Fate and Nature.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Opticks, Query 28 (1704)', 'Whereas the main Business of natural Philosophy is to argue from Phaenomena without feigning Hypotheses, and to deduce Causes from Effects, till we come to the very first Cause, which certainly is not mechanical…', 'truth,creation,wisdom,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'Whereas the main Business of natural Philosophy is to argue from Phaenomena without feigning Hypotheses, and to deduce Causes from Effects, till we come to the very first Cause, which certainly is not mechanical…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Opticks, Query 31 (1704)', 'And if natural Philosophy in all its Parts, by pursuing this Method, shall at length be perfected, the Bounds of Moral Philosophy will be also enlarged. For so far as we can know by natural Philosophy what is the first Cause, what Power he has over us, and what Benefits we receive from him, so far our Duty towards him, as well as that towards one another, will appear to us by the Light of Nature.', 'love_of_neighbor,truth,wisdom,creation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'And if natural Philosophy in all its Parts, by pursuing this Method, shall at length be perfected, the Bounds of Moral Philosophy will be also enlarged. For so far as we can know by natural Philosophy what is the first Cause, what Power he has over us, and what Benefits we receive from him, so far our Duty towards him, as well as that towards one another, will appear to us by the Light of Nature.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Opticks, Query 31 (1704)', 'For while Comets move in very excentrick Orbs in all manner of Positions, blind Fate could never make all the Planets move one and the same way in Orbs concentrick… Such a wonderful Uniformity in the Planetary System must be allowed the Effect of Choice.', 'creation,providence,sovereignty,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'For while Comets move in very excentrick Orbs in all manner of Positions, blind Fate could never make all the Planets move one and the same way in Orbs concentrick… Such a wonderful Uniformity in the Planetary System must be allowed the Effect of Choice.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Letter to Richard Bentley (December 10, 1692)', 'To your second Query I answer that the motions which the Planets now have could not spring from any naturall cause alone but were imprest by an intelligent Agent.', 'creation,sovereignty,faith,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'To your second Query I answer that the motions which the Planets now have could not spring from any naturall cause alone but were imprest by an intelligent Agent.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Cited in David Brewster, Memoirs of the Life, Writings, and Discoveries of Sir Isaac Newton, vol. 2 (1855)', 'We are, therefore, to acknowledge one God, infinite, eternal, omnipresent, omniscient, omnipotent, the Creator of all things, most wise, most just, most good, most holy.', 'faith,worship,sovereignty,holiness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'We are, therefore, to acknowledge one God, infinite, eternal, omnipresent, omniscient, omnipotent, the Creator of all things, most wise, most just, most good, most holy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 66, 'Observations upon the Prophecies of Daniel, Part II, Chapter I (1733)', 'The design of God was much otherwise. He gave this and the Prophecies of the Old Testament, not to gratify men''s curiosities by enabling them to foreknow things, but that after they were fulfilled they might be interpreted by the event, and his own Providence, not the Interpreters, be then manifested thereby to the world.', 'providence,scripture,humility,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 66 AND text = 'The design of God was much otherwise. He gave this and the Prophecies of the Old Testament, not to gratify men''s curiosities by enabling them to foreknow things, but that after they were fulfilled they might be interpreted by the event, and his own Providence, not the Interpreters, be then manifested thereby to the world.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'Essays, Of Adversity (1625)', 'Prosperity is not without many fears and distastes; and adversity is not without comforts and hopes. … Certainly virtue is like precious odors, most fragrant when they are incensed, or crushed: for prosperity doth best discover vice, but adversity doth best discover virtue.', 'suffering,hope,perseverance,virtue', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'Prosperity is not without many fears and distastes; and adversity is not without comforts and hopes. … Certainly virtue is like precious odors, most fragrant when they are incensed, or crushed: for prosperity doth best discover vice, but adversity doth best discover virtue.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'Essays, Of Goodness and Goodness of Nature (1625)', 'If a man be gracious and courteous to strangers, it shows he is a citizen of the world, and that his heart is no island, cut off from other lands, but a continent, that joins to them.', 'compassion,love_of_neighbor,kindness,hospitality', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'If a man be gracious and courteous to strangers, it shows he is a citizen of the world, and that his heart is no island, cut off from other lands, but a continent, that joins to them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'Essays, Of Truth (1625)', 'Certainly, it is heaven upon earth, to have a man''s mind move in charity, rest in providence, and turn upon the poles of truth.', 'truth,providence,love,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'Certainly, it is heaven upon earth, to have a man''s mind move in charity, rest in providence, and turn upon the poles of truth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'Essays, Of Revenge (1625)', 'This is certain, that a man that studieth revenge, keeps his own wounds green, which otherwise would heal, and do well.', 'forgiveness,peace,healing,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'This is certain, that a man that studieth revenge, keeps his own wounds green, which otherwise would heal, and do well.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'The Advancement of Learning, Book I (1605)', 'To conclude, therefore, let no man upon a weak conceit of sobriety or an ill-applied moderation think or maintain that a man can search too far, or be too well studied in the book of God''s word, or in the book of God''s works, divinity or philosophy… only let men beware that they apply both to charity, and not to swelling; to use, and not to ostentation…', 'scripture,creation,love,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'To conclude, therefore, let no man upon a weak conceit of sobriety or an ill-applied moderation think or maintain that a man can search too far, or be too well studied in the book of God''s word, or in the book of God''s works, divinity or philosophy… only let men beware that they apply both to charity, and not to swelling; to use, and not to ostentation…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 70, 'The Advancement of Learning, Book I (1605)', 'But the greatest error of all the rest is the mistaking or misplacing of the last or furthest end of knowledge. … as if there were sought in knowledge a couch whereupon to rest a searching and restless spirit … and not a rich storehouse for the glory of the Creator and the relief of man''s estate.', 'service,wisdom,creation,work', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 70 AND text = 'But the greatest error of all the rest is the mistaking or misplacing of the last or furthest end of knowledge. … as if there were sought in knowledge a couch whereupon to rest a searching and restless spirit … and not a rich storehouse for the glory of the Creator and the relief of man''s estate.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 74, 'Experiments on Plant Hybridization, Introductory Remarks (1866)', 'That, so far, no generally applicable law governing the formation and development of hybrids has been successfully formulated can hardly be wondered at by anyone who is acquainted with the extent of the task, and can appreciate the difficulties with which experiments of this class have to contend.', 'perseverance,humility,work,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 74 AND text = 'That, so far, no generally applicable law governing the formation and development of hybrids has been successfully formulated can hardly be wondered at by anyone who is acquainted with the extent of the task, and can appreciate the difficulties with which experiments of this class have to contend.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 74, 'Experiments on Plant Hybridization, Introductory Remarks (1866)', 'This experiment was practically confined to a small plant group, and is now, after eight years'' pursuit, concluded in all essentials. Whether the plan upon which the separate experiments were conducted and carried out was the best suited to attain the desired end is left to the friendly decision of the reader.', 'humility,perseverance,work,patience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 74 AND text = 'This experiment was practically confined to a small plant group, and is now, after eight years'' pursuit, concluded in all essentials. Whether the plan upon which the separate experiments were conducted and carried out was the best suited to attain the desired end is left to the friendly decision of the reader.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 74, 'Experiments on Plant Hybridization, Concluding Remarks (1866)', 'Whether the variable hybrids of other plant species observe an entire agreement must also be first decided experimentally. In the meantime we may assume that in material points an essential difference can scarcely occur, since the unity in the developmental plan of organic life is beyond question.', 'creation,truth,wisdom,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 74 AND text = 'Whether the variable hybrids of other plant species observe an entire agreement must also be first decided experimentally. In the meantime we may assume that in material points an essential difference can scarcely occur, since the unity in the developmental plan of organic life is beyond question.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 84, 'Cited in William Garden Blaikie, The Personal Life of David Livingstone (1880)', 'Can the love of Christ not carry the missionary where the slave-trade carries the trader?', 'love,courage,mission,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 84 AND text = 'Can the love of Christ not carry the missionary where the slave-trade carries the trader?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 87, 'Cited in Una Roberts Lawrence, Lottie Moon (1927)', 'I wish to carry the gospel to as many as I can reach. … as between school and evangelistic work, being free to choose, I turn to the villages!', 'mission,service,calling,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 87 AND text = 'I wish to carry the gospel to as many as I can reach. … as between school and evangelistic work, being free to choose, I turn to the villages!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 88, 'Cited in Francis Wayland, A Memoir of the Life and Labors of the Rev. Adoniram Judson, vol. 1 (1853)', 'However, I anticipate a happier meeting, brighter plains, friends the same, but more lovely and beloved; … assured that we shall not then regret any instance of self-denial or suffering endured for the Lord of life and glory.', 'hope,self-denial,heaven,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 88 AND text = 'However, I anticipate a happier meeting, brighter plains, friends the same, but more lovely and beloved; … assured that we shall not then regret any instance of self-denial or suffering endured for the Lord of life and glory.');
